content.css:
/* Codex KPI Wall — v2 cell chrome ported from the KPI Card v2 board
 * (docs/design-session-2026-07-09/Codex KPI Card v2.dc.html). Colours that
 * depend on the band engine are set inline from TS via CSS custom props
 * (--band and computed gradients); everything static lives here. */
.codex-visual-root {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
  font-family: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
}
.codex-visual-title {
  padding: 6px 10px 4px;
  line-height: 1.25;
}
.codex-visual-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 8px;
  padding: 16px;
  text-align: center;
}
.codex-visual-empty-title {
  font-size: 15px;
  font-weight: 700;
}
.codex-visual-empty-body {
  font-size: 12px;
  opacity: 0.75;
  max-width: 420px;
}
.kw-grid {
  display: grid;
  box-sizing: border-box;
  width: 100%;
  align-content: start;
}
/* ─── The v2 cell (board .k2) ─────────────────────────────────── */
.kw-card {
  position: relative;
  min-height: 158px;
  border-radius: 10px;
  padding: 16px 20px 14px 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-sizing: border-box;
  overflow: hidden;
  cursor: pointer;
}
/* Accent — flat bar (board .k2bar) */
.kw-bar {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  z-index: 1;
}
/* Accent — glass tube (board .gloss) */
.kw-glassTube .kw-bar {
  width: 7px;
  left: 7px;
  top: 12px;
  bottom: 12px;
  border-radius: 99px;
}
.kw-glassTube .kw-bar::after {
  content: "";
  position: absolute;
  left: 1.5px;
  top: 7%;
  bottom: 7%;
  width: 2.2px;
  border-radius: 99px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.15) 55%, rgba(255, 255, 255, 0.45));
}
/* Accent — corner bracket (board .acccorner / .acc2); colours inline from TS */
.kw-cornerBracket .kw-bar {
  top: 0;
  left: 0;
  bottom: auto;
  width: 52px;
  height: 52px;
  background: none !important;
  border-top: 4px solid;
  border-left: 4px solid;
  border-radius: 10px 0 0 0;
  box-shadow: none !important;
}
.kw-corner2 {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 52px;
  height: 52px;
  border-bottom: 4px solid;
  border-right: 4px solid;
  border-radius: 0 0 10px 0;
  pointer-events: none;
}
.kw-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.kw-eye {
  font-size: 10.5px;
  letter-spacing: 0.16em;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kw-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex: 0 0 auto;
}
.kw-val {
  font-size: 42px;
  line-height: 0.95;
  font-weight: 700;
  font-feature-settings: "tnum";
  letter-spacing: -0.01em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kw-foot {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.kw-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12.5px;
  font-weight: 700;
  font-feature-settings: "tnum";
  padding: 3px 9px;
  border-radius: 999px;
  line-height: 1.3;
}
.kw-sub {
  font-size: 12.5px;
}
.kw-strip {
  display: flex;
  gap: 3px;
  margin-top: 9px;
}
.kw-strip span {
  flex: 1;
  height: 6px;
  border-radius: 2px;
}
/* Per-cell empty state (board .k2.nd) */
.kw-nd {
  justify-content: center;
  align-items: flex-start;
}
.kw-ndv {
  font-size: 34px;
  font-weight: 700;
  opacity: 0.5;
  line-height: 1;
}
.kw-ndt {
  font-size: 12.5px;
  margin-top: 8px;
}
